WITH gated AS (SELECT model FROM llm_gateway.usage_log WHERE {{ time_filter('timestamp') }} AND model != '' GROUP BY model HAVING count() >= 100), sig AS (SELECT model, count() AS reqs, countIf(is_followup = 1) AS fu, countIf(is_followup = 1 AND signal_count > 0) AS rej_n, countIf(is_followup = 0 AND parsed = 1) AS base_n, countIf(is_followup = 0 AND parsed = 1 AND signal_count > 0) AS base_rej FROM llm_gateway.request_signals WHERE {{ time_filter('timestamp') }} AND model IN (SELECT model FROM gated) GROUP BY model), spd AS (SELECT model, countIf(is_stream = 1) AS streams, countIf(aborted = 1) AS cancels, countIf(aborted = 2) AS aborts FROM llm_gateway.usage_log WHERE {{ time_filter('timestamp') }} AND model IN (SELECT model FROM gated) GROUP BY model), sess AS (SELECT session_id, argMax(model, timestamp) AS last_model, groupUniqArray(model) AS models FROM llm_gateway.request_log WHERE {{ time_filter('timestamp') }} AND session_id != '' AND coalesce(nullIf(key_id,''), nullIf(api_key_id,''), 'unknown') IN ({{ gf_str_multi('api_key') }}) GROUP BY session_id), swm AS (SELECT m AS model, countIf(last_model != m) AS switches, count() AS n FROM sess ARRAY JOIN models AS m WHERE m IN (SELECT model FROM gated) GROUP BY m), raw AS (SELECT s.model AS model, s.reqs, 100 * s.rej_n / nullIf(s.fu, 0) AS net_rej, 100 * w.switches / nullIf(w.n, 0) AS switch_rate, 100 * p.cancels / nullIf(p.streams, 0) AS cancel_rate, 100 * p.aborts / nullIf(p.streams, 0) AS abort_rate FROM sig s INNER JOIN spd p ON p.model = s.model LEFT JOIN swm w ON w.model = s.model) SELECT model AS metric, round(100 * sqrt(power(ifNull(least(greatest(1 - net_rej / 50, 0.05), 1), 0.5) * ifNull(least(greatest(1 - switch_rate / 100, 0.05), 1), 0.5) * ifNull(least(greatest(1 - cancel_rate / 5, 0.05), 1), 0.5), 1 / 3) * ifNull(least(greatest(1 - abort_rate / 5, 0.05), 1), 0.5)), 2) AS "Overall Score" FROM raw WHERE reqs >= 30 AND ('{{ gf_num('include_local') }}' = 'yes' OR model NOT IN (SELECT model FROM llm_gateway.model_registry WHERE is_local = 1)) ORDER BY "Overall Score" DESC